            if (pair.sameDayPlanId() != plan.id() && pair.nextDayPlanId() != plan.id()) {
                throw conflict("NIGHT_PAIR_MISMATCH",
                        "计划不属于该夜间计划对: " + req.scheduleKey() + " / " + nightPairKey);
